insert into public.stores(name,slug) values ('London Papelaria & Presentes Criativos','london-papelaria') on conflict(slug) do nothing;
insert into public.catalog_categories(store_id,name) select distinct s.id,p.category from public.stores s cross join jsonb_to_recordset('[{"id":"caderno-rosa","name":"Caderno Espiral Rosé","detail":"Para ideias que merecem ficar.","category":"Cadernos","price_cents":2490,"image_index":0,"tag":"Queridinho"},{"id":"canetas-pastel","name":"Kit Canetas Pastel","detail":"Seis cores, infinitas possibilidades.","category":"Escrita","price_cents":1890,"image_index":1,"tag":""},{"id":"planner-verde","name":"Planner Botânico","detail":"Mais leveza para os seus planos.","category":"Cadernos","price_cents":3990,"image_index":2,"tag":"Para organizar"},{"id":"estojo-lilas","name":"Estojo Lavanda","detail":"Seus essenciais, sempre por perto.","category":"Acessórios","price_cents":2290,"image_index":3,"tag":""},{"id":"blocos-adesivos","name":"Blocos Adesivos Candy","detail":"Um lembrete cheio de cor.","category":"Acessórios","price_cents":1290,"image_index":4,"tag":""},{"id":"kit-presente","name":"Kit Novos Começos","detail":"Um carinho em forma de papelaria.","category":"Presentes","price_cents":5990,"image_index":5,"tag":"Para presentear"}]'::jsonb) p(category text) where s.slug='london-papelaria' on conflict(store_id,name) do nothing;
insert into public.catalog_products(store_id,id,name,detail,category,price_cents,image_index,tag) select s.id,p.* from public.stores s cross join jsonb_to_recordset('[{"id":"caderno-rosa","name":"Caderno Espiral Rosé","detail":"Para ideias que merecem ficar.","category":"Cadernos","price_cents":2490,"image_index":0,"tag":"Queridinho"},{"id":"canetas-pastel","name":"Kit Canetas Pastel","detail":"Seis cores, infinitas possibilidades.","category":"Escrita","price_cents":1890,"image_index":1,"tag":""},{"id":"planner-verde","name":"Planner Botânico","detail":"Mais leveza para os seus planos.","category":"Cadernos","price_cents":3990,"image_index":2,"tag":"Para organizar"},{"id":"estojo-lilas","name":"Estojo Lavanda","detail":"Seus essenciais, sempre por perto.","category":"Acessórios","price_cents":2290,"image_index":3,"tag":""},{"id":"blocos-adesivos","name":"Blocos Adesivos Candy","detail":"Um lembrete cheio de cor.","category":"Acessórios","price_cents":1290,"image_index":4,"tag":""},{"id":"kit-presente","name":"Kit Novos Começos","detail":"Um carinho em forma de papelaria.","category":"Presentes","price_cents":5990,"image_index":5,"tag":"Para presentear"}]'::jsonb) p(id text,name text,detail text,category text,price_cents integer,image_index integer,tag text) where s.slug='london-papelaria' on conflict(store_id,id) do nothing;
